  color: inherit;
  text-decoration: none;
}

.tapt-desktop-viewport :where(input)::placeholder {
  color: rgba(94, 158, 255, 0.5);
}

.tapt-desktop-viewport :where(*) {
  scrollbar-width: none;
}

.tapt-desktop-viewport :where(*)::-webkit-scrollbar {
  width: 0;
  height: 0;
}

.tapt-desktop-frame {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #000926;
}

.tapt-desktop-viewport[data-device-class="desktop"]
  > .tapt-desktop-frame {
  width: min(1000px, 94vw, 126.0455vh);
  height: auto;
  aspect-ratio: 59 / 44;
  border-radius: 28px;
  background: #000f3f;
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.55);
}

@supports (height: 100dvh) {
  .tapt-desktop-viewport[data-device-class="desktop"]
    > .tapt-desktop-frame {
    width: min(1000px, 94vw, 126.0455dvh);
  }
}

.tapt-desktop-viewport[data-device-class="desktop"]
  > .tapt-desktop-frame::after {
  position: absolute;
  z-index: 20;
  inset: 0;
  border: 1px solid rgba(94, 158, 255, 0.18);
  border-radius: inherit;
  pointer-events: none;
  content: "";
}

.tapt-desktop-scale-stage {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #000926;
}

.tapt-desktop-viewport[data-device-class="tablet"],
.tapt-desktop-viewport[data-device-class="tablet"] > .tapt-desktop-frame,
.tapt-desktop-viewport[data-device-class="tablet"] .tapt-desktop-scale-stage {
  background: #f4f4f4;
}

.tapt-desktop-viewport[data-device-class="desktop"]
  .tapt-desktop-scale-stage {
  background: #000f3f;
}

.tapt-desktop-scale-box {
  position: relative;
  flex: 0 0 auto;
  overflow: visible;
}

.tapt-desktop-scale-content {
  position: absolute;
  top: 0;
  left: 0;
  width: 1180px;
  height: 880px;
  max-width: none !important;
  max-height: none !important;
  transform-origin: top left;
}

.tapt-desktop-canvas {
  position: relative;
  width: 1180px;
  height: 880px;
  max-width: none !important;
