130	export async function newRetailPage(browser, label, contextOptions) {
131	  const context = await browser.newContext({
132	    ...contextOptions,
133	    deviceScaleFactor: 1,
134	    serviceWorkers: "block",
135	    timezoneId: "Pacific/Auckland",
136	  });
137	  const page = await context.newPage();
138	  const errors = [];
139	  page.on("pageerror", (error) => errors.push(`${label} page: ${error.message}`));
140	  page.on("console", (message) => {
141	    if (message.type() === "error") errors.push(`${label} console: ${message.text()}`);
142	  });
143	  page.on("requestfailed", (request) => {
144	    errors.push(`${label} request failed: ${request.method()} ${request.url()} — ${request.failure()?.errorText ?? "unknown"}`);
145	  });
146	  page.on("response", (response) => {
147	    if (response.status() < 400) return;
148	    try {
149	      const url = new URL(response.url());
150	      if (url.origin !== new URL(BASE_URL).origin) return;
151	      errors.push(
152	        `${label} HTTP ${response.status()}: ${response.request().method()} ${url.pathname}${url.search}`,
153	      );
154	    } catch {
155	      errors.push(`${label} HTTP ${response.status()}: ${response.url()}`);
156	    }
157	  });
158	  await installRetailMocks(page);
159	  return { context, page, errors };
160	}
161	
162	export async function runRetailShots(shoot) {
163	  const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
164	  try {
165	    const desktop = await shoot(browser, "desktop", {
166	      viewport: { width: 1440, height: 900 },
167	    });
168	    const tablet = await shoot(browser, "tablet", {
169	      viewport: { width: 1194, height: 834 },
170	      hasTouch: true,
171	      isMobile: false,
172	    });
173	    const errors = [...desktop, ...tablet];
174	    if (errors.length) throw new Error(`PAGE ERRORS:\n${errors.join("\n")}`);
175	    console.log("no page errors");
176	  } finally {
177	    await browser.close();
178	  }
179	}
