5	import { useToast } from "@/hooks/use-toast";
6	import {
7	  DesktopPageScaffold,
8	  type DesktopRoutePageProps,
9	} from "../DesktopPageScaffold";
10	import {
11	  DESKTOP_KEYPAD_KEYS,
12	  DesktopKeypadButton,
13	  desktopKeypadCents,
14	  desktopKeypadReducer,
15	  formatDesktopKeypadMoney,
16	  type DesktopKeypadKey,
17	} from "../desktop-keypad";
18	
19	/* ── palette ── */
20	const ACCENT = "#5E9EFF";
21	const ACCENT_SOFT = "#7FB2FF";
22	const NAV_DIM = "#4A86F0";
23	const ACTIVE = "#66A9FF";
24	const TEXT_SOFT = "#F4F6FF";
25	const NAVY = "#000F3F";
26	const INK = "#12162E";
27	const DEEP_BLUE = "#1D48C8";
28	const KP_INK = "#C6CFE2";
29	const GREEN = "#35D07F";
30	const RED = "#F0656C";
31	const AMBER = "#F0A34E";
32	const VIOLET = "#9DBCFF";
33	
34	type Mode = "send" | "keypad" | "stock" | "split" | "share";
35	
36	type SaleDestination =
37	  | { kind: "no-board" }
38	  | { kind: "board"; boardId: number };
39	
40	interface CreateSaleInput {
41	  item: string;
42	  price: string;
43	  splitEnabled: boolean;
44	  destination: SaleDestination;
45	}
46	
47	interface CreatedSaleResponse {
48	  id?: number;
49	  paymentUrl?: string | null;
50	  qrCodeUrl?: string | null;
51	}
52	
53	interface CurrentSale {
54	  item: string;
55	  amount: number;
56	  paymentUrl: string;
57	  qrCodeUrl: string;
58	  destination: SaleDestination;
59	}
60	
61	interface Tx {
62	  id: number;
63	  status: string;
64	  itemName?: string;
65	  price?: string;
66	  taptStoneId?: number | null;
67	  isSplit?: boolean | null;
68	  totalSplits?: number | null;
69	  completedSplits?: number | null;
70	  splitAmount?: string | null;
71	  createdAt: string;
72	}
73	interface StockItem {
74	  id: number;
75	  name: string;
76	  cost: string | number;
77	  emoji?: string | null;
78	}
79	interface Stone {
80	  id: number;
81	  name: string;
82	  stoneNumber: number;
83	  paymentUrl?: string | null;
84	  qrCodeUrl?: string | null;
85	}
86	
87	const BOARD_LIMIT_MESSAGE = "Maximum 10 tapt stones allowed per merchant";
88	
89	function apiErrorDetails(error: unknown): { status: number | null; message: string } {
90	  const raw = error instanceof Error ? error.message : String(error ?? "");
91	  const statusMatch = raw.match(/^(\d{3}):\s*/);
92	  const status = statusMatch ? Number(statusMatch[1]) : null;
93	  const withoutStatus = statusMatch ? raw.slice(statusMatch[0].length) : raw;
94	  const jsonStart = withoutStatus.indexOf("{");
95	  if (jsonStart >= 0) {
96	    try {
97	      const parsed = JSON.parse(withoutStatus.slice(jsonStart));
98	      if (typeof parsed?.message === "string" && parsed.message.trim()) {
99	        return { status, message: parsed.message.trim() };
100	      }
101	    } catch {
102	      /* Fall through to the server text below. */
103	    }
104	  }
105	  return { status, message: withoutStatus.trim() };
106	}
107	
108	const num = (p: unknown) => parseFloat(String(p ?? "0") || "0") || 0;
109	const money2 = (n: number) =>
110	  "$" + n.toLocaleString("en-NZ", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
111	const moneyWhole = (n: number) => "$" + Math.round(n).toLocaleString("en-NZ");
112	
113	function initials(name: string): string {
114	  const parts = String(name ?? "")
115	    .trim()
116	    .split(/\s+/)
117	    .filter((p) => /^[a-z0-9]/i.test(p));
118	  if (parts.length === 0) return "–";
119	  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
120	  return (parts[0][0] + parts[1][0]).toUpperCase();
121	}
122	
123	type Bucket = "awaiting" | "paid" | "failed" | "refunded";
124	
125	/* Raw transaction status → the design's stack buckets. */
126	function statusMeta(status: string): { bucket: Bucket; label: string; dot: string } {
127	  switch (status) {
128	    case "completed":
129	      return { bucket: "paid", label: "paid", dot: GREEN };
130	    case "failed":
131	    case "cancelled":
132	      return { bucket: "failed", label: status === "cancelled" ? "cancelled" : "failed", dot: RED };
133	    case "refunded":
134	      return { bucket: "refunded", label: "refunded", dot: VIOLET };
135	    case "partially_refunded":
136	      return { bucket: "refunded", label: "partly refunded", dot: VIOLET };
137	    default:
138	      return { bucket: "awaiting", label: "awaiting payment", dot: AMBER };
139	  }
140	}
141	
142	const STACK_FILTERS = ["all", "awaiting payment", "paid", "failed"] as const;
143	type StackFilter = (typeof STACK_FILTERS)[number];
144	const FILTER_BUCKET: Record<StackFilter, Bucket | null> = {
145	  all: null,
146	  "awaiting payment": "awaiting",
147	  paid: "paid",
148	  failed: "failed",
149	};
150	
151	const QUICK_AMTS = ["5", "10", "15", "20"] as const;
152	const SPLIT_WAYS = [2, 3, 4, 6] as const;
153	
154	export default function DesktopRetailTerminal(props: DesktopRoutePageProps) {
155	  const merchantId = getCurrentMerchantId();
156	  const queryClient = useQueryClient();
157	  const { toast } = useToast();
158	
159	  const [mode, setMode] = useState<Mode>("send");
160	  const [amount, setAmount] = useState(0);
161	  const [kpVal, setKpVal] = useState("");
162	  const [itemName, setItemName] = useState("");
163	  const [destination, setDestination] = useState<SaleDestination>({ kind: "no-board" });
164	  const [currentSale, setCurrentSale] = useState<CurrentSale | null>(null);
165	  const [saleError, setSaleError] = useState<string | null>(null);
166	  const [boardError, setBoardError] = useState<string | null>(null);
167	  const [splitOn, setSplitOn] = useState(false);
168	  const [splitN, setSplitN] = useState<number>(2);
169	  const [search, setSearch] = useState("");
170	  const [filter, setFilter] = useState<StackFilter>("all");
171	  const [copiedKey, setCopiedKey] = useState<string | null>(null);
172	  const [expandedId, setExpandedId] = useState<number | null>(null);
173	  /* Board picker: `boardsOn` is the disclosure — off means the sale gets a
174	     private per-payment link (the old "no board" choice), on reveals the
175	     picker. `draftName` is shared by the rename and create rows, which are
176	     mutually exclusive. */
177	  const [boardsOn, setBoardsOn] = useState(false);
178	  const [pickerOpen, setPickerOpen] = useState(false);
179	  const [editingId, setEditingId] = useState<number | null>(null);
180	  const [creatingBoard, setCreatingBoard] = useState(false);
181	  const [draftName, setDraftName] = useState("");
182	
183	  const authFetch = async (path: string) => {
184	    const token = localStorage.getItem("authToken");
185	    const res = await fetch(path, { headers: { Authorization: `Bearer ${token}` } });
186	    if (!res.ok) throw new Error(path);
187	    return res.json();
188	  };
189	
190	  const merchantQuery = useQuery<any>({
191	    queryKey: ["/api/merchants", merchantId, "profile"],
192	    queryFn: () => authFetch(`/api/merchants/${merchantId}/profile`),
193	    enabled: !!merchantId,
194	  });
195	
196	  const txQuery = useQuery<Tx[]>({
197	    queryKey: ["/api/merchants", merchantId, "transactions"],
198	    queryFn: () => authFetch(`/api/merchants/${merchantId}/transactions`),
199	    refetchInterval: 5000,
200	    enabled: !!merchantId,
201	  });
202	
203	  const stockQuery = useQuery<StockItem[]>({
204	    queryKey: ["/api/merchants", merchantId, "stock-items"],
205	    queryFn: () => authFetch(`/api/merchants/${merchantId}/stock-items`),
206	    enabled: !!merchantId,
207	  });
208	
209	  const stonesQuery = useQuery<Stone[]>({
210	    queryKey: ["/api/merchants", merchantId, "tapt-stones"],
211	    queryFn: () => authFetch(`/api/merchants/${merchantId}/tapt-stones`),
212	    enabled: !!merchantId,
213	  });
214	
215	  const transactions = txQuery.data ?? [];
216	  const stockItems = stockQuery.data ?? [];
217	  const stones = stonesQuery.data ?? [];
218	  const merchant = merchantQuery.data;
219	
220	  const createMutation = useMutation<CreatedSaleResponse, Error, CreateSaleInput>({
221	    mutationFn: async (sale) => {
222	      const res = await apiRequest("POST", "/api/transactions", {
223	        merchantId,
224	        itemName: sale.item,
225	        price: sale.price,
226	        status: "pending",
227	        splitEnabled: sale.splitEnabled,
228	        ...(sale.destination.kind === "no-board"
229	          ? { linkMode: "per_payment" }
230	          : { selectedStoneId: sale.destination.boardId, linkMode: "legacy" }),
231	      });
232	      return res.json();
233	    },
234	    onMutate: () => {
235	      /* The raw credential is intentionally returned once. Never leave the
236	         previous one visible while another request is pending or fails. */
237	      setCurrentSale(null);
238	      setSaleError(null);
239	      setCopiedKey(null);
240	    },
241	    onSuccess: (created, sale) => {
242	      void queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "transactions"] });
243	      void queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "active-transaction"] });
244	
245	      const paymentUrl = typeof created?.paymentUrl === "string" ? created.paymentUrl.trim() : "";
246	      const qrCodeUrl = typeof created?.qrCodeUrl === "string" ? created.qrCodeUrl.trim() : "";
247	      if (!paymentUrl || !qrCodeUrl) {
248	        const message = "The sale was created, but its private share link was not returned. Start a new sale to try again.";
249	        setSaleError(message);
250	        setMode("share");
251	        toast({ title: "Payment link unavailable", description: message, variant: "destructive" });
252	      } else {
253	        setCurrentSale({
254	          item: sale.item,
255	          amount: num(sale.price),
256	          paymentUrl,
257	          qrCodeUrl,
258	          destination: sale.destination,
259	        });
260	        setMode("share");
261	      }
262	      setItemName("");
263	      setAmount(0);
264	      setSplitOn(false);
265	    },
266	    onError: (error) => {
267	      /* 402 BILLING_CARD_REQUIRED surfaces its own persistent warning via apiRequest. */
268	      const detail = apiErrorDetails(error);
269	      const message = detail.message || "Please try again";
270	      setSaleError(message);
271	      toast({ title: "Couldn't start the sale", description: message, variant: "destructive" });
272	    },
273	  });
274	
275	  const createBoardMutation = useMutation<Stone, Error, string | undefined>({
276	    mutationFn: async (name) => {
277	      const trimmed = name?.trim();
278	      const res = await apiRequest(
279	        "POST",
280	        `/api/merchants/${merchantId}/tapt-stones`,
281	        trimmed ? { name: trimmed } : {},
282	      );
283	      return res.json();
284	    },
285	    onMutate: () => setBoardError(null),
286	    onSuccess: (created) => {
287	      if (typeof created?.id !== "number") {
288	        const message = "New board created, but its details could not be loaded";
289	        setBoardError(message);
290	        void stonesQuery.refetch();
291	        return;
292	      }
293	      setCreatingBoard(false);
294	      setDraftName("");
295	      setBoardsOn(true);
296	      setPickerOpen(false);
297	      queryClient.setQueryData<Stone[]>(
298	        ["/api/merchants", merchantId, "tapt-stones"],
299	        (current = []) =>
300	          [...current.filter((stone) => stone.id !== created.id), created].sort(
301	            (a, b) => a.stoneNumber - b.stoneNumber,
302	          ),
303	      );
304	      setDestination({ kind: "board", boardId: created.id });
305	      setBoardError(null);
306	      void queryClient.invalidateQueries({
307	        queryKey: ["/api/merchants", merchantId, "tapt-stones"],
308	      });
309	      toast({ title: "New board created", description: `${created.name} selected` });
310	    },
311	    onError: (error) => {
312	      const detail = apiErrorDetails(error);
313	      const message = detail.message || "Failed to create a new board";
314	      setBoardError(message);
315	      if (detail.status === 409) void stonesQuery.refetch();
316	      toast({
317	        title: message === BOARD_LIMIT_MESSAGE ? "Board limit reached" : "Couldn't create board",
318	        description: message,
319	        variant: "destructive",
320	      });
321	    },
322	  });
323	
324	  const renameBoardMutation = useMutation<Stone, Error, { id: number; name: string }>({
325	    mutationFn: async ({ id, name }) => {
326	      const res = await apiRequest(
327	        "PUT",
328	        `/api/merchants/${merchantId}/tapt-stones/${id}`,
329	        { name: name.trim() },
330	      );
331	      return res.json();
332	    },
333	    onMutate: () => setBoardError(null),
334	    onSuccess: (updated, { id, name }) => {
335	      /* The server echoes the row back, but fall back to the local name so the
336	         list still updates if the response shape ever changes. */
337	      queryClient.setQueryData<Stone[]>(
338	        ["/api/merchants", merchantId, "tapt-stones"],
339	        (current = []) =>
340	          current.map((stone) =>
341	            stone.id === id ? { ...stone, ...updated, name: updated?.name ?? name.trim() } : stone,
342	          ),
343	      );
344	      setEditingId(null);
345	      setDraftName("");
346	      void queryClient.invalidateQueries({
347	        queryKey: ["/api/merchants", merchantId, "tapt-stones"],
348	      });
349	    },
350	    onError: (error) => {
351	      const message = apiErrorDetails(error).message || "Couldn't rename that board";
352	      setBoardError(message);
353	      toast({ title: "Couldn't rename board", description: message, variant: "destructive" });
354	    },
355	  });
356	
357	  const cancelMutation = useMutation({
358	    mutationFn: async (transactionId: number) => {
359	      const res = await apiRequest("POST", `/api/transactions/${transactionId}/cancel`, {});
360	      return res.json();
361	    },
362	    onSuccess: () => {
363	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "transactions"] });
364	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "active-transaction"] });
365	      toast({ title: "Transaction cancelled" });
366	      setExpandedId(null);
367	    },
368	    onError: () => toast({ title: "Failed to cancel", variant: "destructive" }),
369	  });
370	
371	  /* ── derived ── */
372	  const { revenueToday, txnsToday, pctVsYesterday } = useMemo(() => {
373	    const dayStart = new Date();
374	    dayStart.setHours(0, 0, 0, 0);
375	    const prevStart = new Date(dayStart.getTime() - 86_400_000);
376	
377	    let today = 0;
378	    let yesterday = 0;
379	    let count = 0;
380	    for (const t of transactions) {
381	      const at = new Date(t.createdAt);
382	      if (at >= dayStart) {
383	        count += 1;
384	        if (t.status === "completed") today += num(t.price);
385	      } else if (at >= prevStart) {
386	        if (t.status === "completed") yesterday += num(t.price);
387	      }
388	    }
389	    return {
390	      revenueToday: today,
391	      txnsToday: count,
392	      pctVsYesterday: yesterday > 0 ? Math.round(((today - yesterday) / yesterday) * 100) : null,
393	    };
394	  }, [transactions]);
395	
396	  const stackRows = useMemo(() => {
397	    const q = search.trim().toLowerCase();
398	    const want = FILTER_BUCKET[filter];
399	    return [...transactions]
400	      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
401	      .map((t) => ({ ...t, meta: statusMeta(t.status) }))
402	      .filter((t) => (want === null ? true : t.meta.bucket === want))
403	      .filter((t) => (t.itemName ?? "").toLowerCase().includes(q));
404	  }, [transactions, search, filter]);
405	
406	  const splitEach = splitN > 0 ? amount / splitN : amount;
407	  const selectedBoard =
408	    destination.kind === "board"
409	      ? stones.find((stone) => stone.id === destination.boardId)
410	      : undefined;
411	  const currentSaleBoardId =
412	    currentSale?.destination.kind === "board" ? currentSale.destination.boardId : null;
413	  const currentSaleBoard =
414	    currentSaleBoardId == null
415	      ? undefined
416	      : stones.find((stone) => stone.id === currentSaleBoardId);
417	  const atBoardLimit = stones.length >= 10;
418	  const boardLabel = (stone: Stone) => stone.name || `board ${stone.stoneNumber}`;
419	
420	  /* ── board picker ── */
421	  /* Enter commits by blurring the field rather than submitting directly, so the
422	     keyboard and click-away paths share one commit and can't fire it twice.
423	     Escape sets this flag so the blur it triggers discards instead. */
424	  const abandonEditRef = useRef(false);
425	  const closePickerEdits = () => {
426	    setEditingId(null);
427	    setCreatingBoard(false);
428	    setDraftName("");
429	  };
430	  const editKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
431	    if (e.key === "Enter") {
432	      e.preventDefault();
433	      e.currentTarget.blur();
434	    } else if (e.key === "Escape") {
435	      abandonEditRef.current = true;
436	      e.currentTarget.blur();
437	    }
438	  };
439	  const editBlur = (commit: () => void) => {
440	    if (abandonEditRef.current) {
441	      abandonEditRef.current = false;
442	      closePickerEdits();
443	      return;
444	    }
445	    commit();
446	  };
447	
448	  /* Turning the disclosure off returns the sale to a private per-payment link,
449	     so the destination has to reset with it — otherwise a hidden board would
450	     keep being charged. */
451	  const toggleBoards = () => {
452	    setBoardsOn((on) => {
453	      if (on) {
454	        setPickerOpen(false);
455	        closePickerEdits();
456	        setDestination({ kind: "no-board" });
457	        setBoardError(null);
458	        return false;
459	      }
460	      /* Engaging boards only reveals the picker button — opening the list is a
461	         separate, deliberate click. */
462	      return true;
463	    });
464	  };
465	
466	  const selectBoard = (id: number) => {
467	    setDestination({ kind: "board", boardId: id });
468	    setPickerOpen(false);
469	    closePickerEdits();
470	  };
471	
472	  const beginRename = (stone: Stone) => {
473	    setCreatingBoard(false);
474	    setEditingId(stone.id);
475	    setDraftName(boardLabel(stone));
476	  };
477	
478	  const commitRename = (id: number) => {
479	    const name = draftName.trim();
480	    if (!name) {
481	      closePickerEdits();
482	      return;
483	    }
