/* Measure the retail terminal's rail and per-mode content geometry, in canvas
   (logical 1180x880) coordinates, so a layout contract can be written against
   real numbers rather than guesses. */
import { mkdir } from "node:fs/promises";
import { BASE_URL, newRetailPage } from "/home/runner/workspace/scripts/desktop-shots/retail-fixtures.mjs";
import { chromium } from "/home/runner/workspace/node_modules/playwright/index.mjs";

const CHROMIUM_PATH =
  "/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium";
const OUT = "/tmp/claude-1000/-home-runner-workspace/e250668d-66ab-4253-93b0-0a4d7795f53f/scratchpad/shots";

const MODES = [
  ["send", "compose sale"],
  ["keypad", "keypad"],
  ["stock", "stock tiles"],
  ["split", "split bill"],
  ["share", "share payment link"],
];

await mkdir(OUT, { recursive: true });
const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
try {
  const { context, page } = await newRetailPage(browser, "terminal", {
    viewport: { width: 1440, height: 900 },
  });
  try {
    await page.goto(`${BASE_URL}/terminal`, { waitUntil: "networkidle" });
    await page.getByTestId("desktop-frame").waitFor({ state: "visible" });
    await page.waitForTimeout(900);

    const measure = (selectors) =>
      page.evaluate((sels) => {
        const canvas = document.querySelector(".tapt-desktop-canvas");
        const scale = Number(
          document.querySelector("[data-desktop-scale]")?.getAttribute("data-desktop-scale") ?? 1,
        );
        const cRect = canvas.getBoundingClientRect();
        const toLogical = (r) => ({
          x: Math.round((r.x - cRect.x) / scale),
          y: Math.round((r.y - cRect.y) / scale),
          w: Math.round(r.width / scale),
          h: Math.round(r.height / scale),
          bottom: Math.round((r.bottom - cRect.y) / scale),
          right: Math.round((r.right - cRect.x) / scale),
        });
        const out = {};
        for (const sel of sels) {
          const el = document.querySelector(sel);
          out[sel] = el ? toLogical(el.getBoundingClientRect()) : null;
        }
        return out;
      }, selectors);

    const rail = await measure([".rt-rail", ".rt-body", ".rt-panel", ".rt-left", ".rt-stack", ".rt-rows", ".rt-chips", ".rt-stack-head"]);
    console.log("RAIL/SHELL", JSON.stringify(rail, null, 1));

    for (const [mode, label] of MODES) {
      await page.getByRole("button", { name: label, exact: true }).click();
      await page.waitForTimeout(500);
      const sels = {
        send: [".rt-send-top", ".rt-amt", ".rt-send-lower", ".rt-send-btn", ".rt-item-name"],
        keypad: [".rt-keypad", ".rt-kp-head", ".rt-kp-amt", ".rt-kp-grid"],
        stock: [".rt-stock", ".rt-stock-head", ".rt-stock-grid"],
        split: [".rt-split", ".rt-amt", ".rt-split-body", ".rt-split-chips", ".rt-send-btn-split"],
        share: [".rt-share", ".rt-share-head", ".rt-share-body", ".rt-new-sale", ".rt-share-empty-state"],
      }[mode];
      const got = await measure(sels);
      console.log(`MODE ${mode}`, JSON.stringify(got, null, 1));
      await page.screenshot({ path: `${OUT}/terminal-${mode}.png` });
    }
  } finally {
    await context.close();
  }
} finally {
  await browser.close();
}
console.log("done");

