import { chromium } from "/home/runner/workspace/node_modules/playwright/index.mjs";
const CHROMIUM_PATH = "/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium";
const DIR = "/tmp/claude-1000/-home-runner-workspace/e250668d-66ab-4253-93b0-0a4d7795f53f/scratchpad";
const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
for (const scheme of ["light", "dark"]) {
  const ctx = await browser.newContext({ viewport: { width: 1100, height: 1200 }, colorScheme: scheme, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  const errs = [];
  page.on("pageerror", e => errs.push(String(e)));
  page.on("console", m => { if (m.type() === "error") errs.push(m.text()); });
  await page.goto("file://" + DIR + "/plan.html", { waitUntil: "networkidle" });
  await page.waitForTimeout(600);
  const info = await page.evaluate(() => ({
    fontLoaded: document.fonts.check('700 40px Outfit'),
    bodyBg: getComputedStyle(document.body).backgroundColor,
    bodyColor: getComputedStyle(document.body).color,
    hOverflow: document.documentElement.scrollWidth > document.documentElement.clientWidth,
    scrollW: document.documentElement.scrollWidth,
    clientW: document.documentElement.clientWidth,
    height: document.body.scrollHeight,
  }));
  console.log(scheme, JSON.stringify(info), errs.length ? "ERRORS:" + errs.join("|") : "clean");
  await page.screenshot({ path: `${DIR}/shots/plan-${scheme}-top.png` });
  await page.evaluate(() => window.scrollTo(0, 1750));
  await page.waitForTimeout(200);
  await page.screenshot({ path: `${DIR}/shots/plan-${scheme}-fig.png` });
  await ctx.close();
}
// narrow check
const ctx = await browser.newContext({ viewport: { width: 420, height: 900 }, colorScheme: "light" });
const p = await ctx.newPage();
await p.goto("file://" + DIR + "/plan.html", { waitUntil: "networkidle" });
await p.waitForTimeout(400);
console.log("narrow overflow:", await p.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth), await p.evaluate(() => document.documentElement.scrollWidth));
await p.screenshot({ path: `${DIR}/shots/plan-narrow.png` });
await ctx.close();
await browser.close();
EOF
